	@Override
	public List<Perso> getAllPersoBySearchForm(PersoSearchForm psf) {
		CriteriaBuilder cb = entityManager.getCriteriaBuilder();
		CriteriaQuery<Perso> cq = cb.createQuery(Perso.class);
		Root<Perso> perso = cq.from(Perso.class);
		List<Predicate> predicates = new ArrayList<>();

		// Filter by type
		if (psf.getType() != null && !psf.getType().isEmpty()) {
			predicates.add(cb.equal(perso.get("type"), psf.getType()));
		}

		// Filter by clientNumber
		if (psf.getClientNumber() != null && !psf.getClientNumber().isEmpty()) {
			predicates.add(cb.like(perso.get("clientNumber"), "%" + psf.getClientNumber() + "%"));
		}

		// Filter by cardNumber
		if (psf.getCardNumber() != null && !psf.getCardNumber().isEmpty()) {
			String cardTrimed = psf.getCardNumber().trim();
			String firstFour = cardTrimed.substring(0, 4);
			int start = cardTrimed.length() - 4;
			String lastFour = cardTrimed.substring(start, cardTrimed.length());
			predicates.add(cb.like(perso.get("cardFirstFour"), "%" + firstFour + "%"));
			predicates.add(cb.like(perso.get("cardLastFour"), "%" + lastFour + "%"));
		}

		// Filter by dateRange
		if (psf.getDateRange() != null && !psf.getDateRange().isEmpty()) {
			if (psf.getDateRange().size() > 0 && psf.getDateRange().get(0) != null) {
				LocalDateTime startDate = psf.getDateRange().get(0).toLocalDate().atStartOfDay();
				predicates.add(cb.greaterThanOrEqualTo(perso.get("fileImportTime"), Timestamp.valueOf(startDate)));
			}
			if (psf.getDateRange().size() > 1 && psf.getDateRange().get(1) != null) {
				LocalDateTime endDate = psf.getDateRange().get(1).toLocalDate().atTime(LocalTime.MAX);
				predicates.add(cb.lessThanOrEqualTo(perso.get("fileImportTime"), Timestamp.valueOf(endDate)));
			}
		}

		// Filter by OPxcode
		if (psf.getPxCode() != null && !psf.getPxCode().isEmpty()) {
			predicates.add(cb.equal(perso.get("OPxcode"), psf.getPxCode()));
		}

		// Filter by inStatus (if list contains statuses)
		if (psf.getInStatus() != null && !psf.getInStatus().isEmpty()) {
			predicates.add(perso.get("status").in(psf.getInStatus()));
		}

		// is Not null px if branch searhc
		if (psf.isBranchRole()) {
			predicates.add(cb.isNotNull(perso.get("OPxcode")));
		}

		// Apply where conditions
		cq.where(predicates.toArray(new Predicate[0]));

		List<Perso> pins = entityManager.createQuery(cq).getResultList();
		pins.forEach(this::maskedCardNumber); // Mask card number if needed
		return pins;
	}

	public void maskedCardNumber(Perso perso) {
		String cardNumber = perso.getCardNumber();
		if (cardNumber == null) {
			return;
		}
		cardNumber = cardNumber.trim();
		if (cardNumber.length() != 16) {
			return;
		}
		String first4 = cardNumber.substring(0, 4);
		String last4 = cardNumber.substring(12, 16);
		String maskedNumber = first4 + " **** **** " + last4;
		perso.setCardNumber(maskedNumber);
	}

